const patientsByName = `-- name: PatientsByName :many
SELECT patient_id, clinical_id, name_en, name_bn, sex, birth_date, dob_precision,
       phone_primary, district, upazila, status, merged_into_id, registered_at,
       GREATEST(
         CASE WHEN $1::text <> '' AND name_key_en = $1::text THEN 0.92 ELSE 0 END,
         CASE WHEN $2::boolean THEN similarity(name_en, $3::text) ELSE 0 END,
         CASE WHEN $4::boolean AND name_bn <> '' THEN similarity(name_bn, $3::text) ELSE 0 END,
         CASE WHEN $2::boolean AND $1::text <> '' AND name_key_en <> ''
              THEN similarity(name_key_en, $1::text) * 0.9 ELSE 0 END
       )::real AS rank
  FROM read.patient
 WHERE facility_id = $5
   AND ($6::boolean OR status <> 'merged')
   AND (
        ($2::boolean AND name_en % $3::text)
     OR ($4::boolean AND name_bn <> '' AND name_bn % $3::text)
     OR ($2::boolean AND $1::text <> '' AND name_key_en <> ''
         AND name_key_en % $1::text)
   )
 ORDER BY rank DESC, registered_at DESC, patient_id
 LIMIT $8::int OFFSET $7::int
`

type PatientsByNameParams struct {
	NameKey       string
	Latin         bool
	Term          string
	Bangla        bool
	FacilityID    uuid.UUID
	IncludeMerged bool
	PageOffset    int32
	PageSize      int32
}

type PatientsByNameRow struct {
	PatientID    uuid.UUID
	ClinicalID   string
	NameEn       string
	NameBn       string
	Sex          string
	BirthDate    time.Time
	DobPrecision string
	PhonePrimary string
	District     string
	Upazila      string
	Status       string
	MergedIntoID uuid.NullUUID
	RegisteredAt time.Time
	Rank         float32
}

// The fuzzy route. Trigram indexes on both name columns and on the phonetic key, ranked by
// the best of them.
//
// `bangla` and `latin` say which scripts the term is written in, decided in Go. Without
// them a Latin search still pays to compute `similarity(name_bn, 'Rahim')` for every
// matching row — a comparison that can never be above zero — and at fifty thousand patients
// that is a measurable share of the search budget (CP31).
func (q *Queries) PatientsByName(ctx context.Context, arg PatientsByNameParams) ([]PatientsByNameRow, error) {
	rows, err := q.db.Query(ctx, patientsByName,
		arg.NameKey,
		arg.Latin,
		arg.Term,
		arg.Bangla,
		arg.FacilityID,
		arg.IncludeMerged,
		arg.PageOffset,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PatientsByNameRow{}
	for rows.Next() {
		var i PatientsByNameRow
		if err := rows.Scan(
			&i.PatientID,
			&i.ClinicalID,
			&i.NameEn,
			&i.NameBn,
			&i.Sex,
			&i.BirthDate,
			&i.DobPrecision,
			&i.PhonePrimary,
			&i.District,
			&i.Upazila,
			&i.Status,
			&i.MergedIntoID,
			&i.RegisteredAt,
			&i.Rank,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

